"use strict";(self.webpackChunkdocusaurus_wiki=self.webpackChunkdocusaurus_wiki||[]).push([[5844],{3658:(e,l,u)=>{u.r(l),u.d(l,{assets:()=>o,contentTitle:()=>s,default:()=>c,frontMatter:()=>n,metadata:()=>r,toc:()=>m});var t=u(7462),a=(u(7294),u(3905)),i=(u(6256),u(3767));const n={title:"Jumelle mal\xe9fique"},s=void 0,r={unversionedId:"roles/jumelle-malefique",id:"roles/jumelle-malefique",title:"Jumelle mal\xe9fique",description:"Description",source:"@site/docs/roles/jumelle-malefique.mdx",sourceDirName:"roles",slug:"/roles/jumelle-malefique",permalink:"/botc-wiki/docs/roles/jumelle-malefique",draft:!1,tags:[],version:"current",frontMatter:{title:"Jumelle mal\xe9fique"}},o={},m=[{value:"Description",id:"description",level:3},{value:"Exemples",id:"exemples",level:3},{value:"M\xe9caniques et conseils",id:"m\xe9caniques-et-conseils",level:3},{value:"Combattre la Jumelle mal\xe9fique",id:"combattre-la-jumelle-mal\xe9fique",level:3},{value:"Comment conter?",id:"comment-conter",level:3}],p={toc:m};function c(e){let{components:l,...u}=e;return(0,a.kt)("wrapper",(0,t.Z)({},p,u,{components:l,mdxType:"MDXLayout"}),(0,a.kt)(i.Z,{JUMELLE_MALEFIQUE:!0,header:!0,mdxType:"Role"}),(0,a.kt)("h3",{id:"description"},"Description"),(0,a.kt)("p",null,"Vous et un joueur d'alignement oppos\xe9 vous connaissez. Si le joueur gentil est ex\xe9cut\xe9, les mal\xe9fiques gagnent. Le village ne peut pas gagner si vous \xeates tous les deux en vie."),(0,a.kt)("p",null,"La Jumelle mal\xe9fique usurpe le r\xf4le d\u2019un joueur gentil afin que le village ne sache pas quel jumeau est gentil et quel jumeau est mal\xe9fique."),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"La Jumelle mal\xe9fique est en paire avec un joueur gentil choisi par le Conteur qui sera consid\xe9r\xe9 comme la jumelle gentille.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"La premi\xe8re nuit, la Jumelle mal\xe9fique et la jumelle gentille se r\xe9veillent ensemble pour un contact visuel et apprennent le r\xf4le de chacun.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si la jumelle gentille est ex\xe9cut\xe9, les mal\xe9fiques l\u2019emporte. Si la Jumelle mal\xe9fique est ex\xe9cut\xe9, la partie continue. Une Jumelle mal\xe9fique mort n\u2019a pas de capacit\xe9 donc les mal\xe9fiques ne gagnent pas si la jumelle gentille est ex\xe9cut\xe9 apr\xe8s. Le village ne peut pas gagner tant que les deux jumelles sont en vie. M\xeame si le D\xe9mon est mort, la partie continue. Le village doit tuer la Jumelle mal\xe9fique ET le D\xe9mon pour gagner.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si un joueur gentil est transform\xe9 en Jumelle mal\xe9fique, il est toujours gentil et un joueur mal\xe9fique devient son jumeau. Peu importe quel jumeau est quel r\xf4le. Ce qui importe est leur alignement. Le village peut sereinement ex\xe9cuter le joueur mal\xe9fique mais s\u2019il ex\xe9cute le joueur gentil, les mal\xe9fiques gagnent.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si les deux jumelles sont du m\xeame alignement, le Conteur choisit un nouveau jumeau."))),(0,a.kt)("h3",{id:"exemples"},"Exemples"),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"Les deux jumelles pr\xe9tendent \xeatre l\u2019",(0,a.kt)(i.Z,{ORACLE:!0,mdxType:"Role"}),". La Jumelle mal\xe9fique est ex\xe9cut\xe9. La partie continue.")),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"La ",(0,a.kt)(i.Z,{GUENAUDE:!0,mdxType:"Role"})," transforme le ",(0,a.kt)(i.Z,{SAGE:!0,mdxType:"Role"}),", qui est aussi la jumelle Villageoise en ",(0,a.kt)(i.Z,{BETE_DE_FOIRE:!0,mdxType:"Role"}),". Les deux jumelles essayent de convaincre le groupe qu\u2019ils sont la ",(0,a.kt)(i.Z,{BETE_DE_FOIRE:!0,mdxType:"Role"}),". Le Conteur ex\xe9cute imm\xe9diatement la ",(0,a.kt)(i.Z,{BETE_DE_FOIRE:!0,mdxType:"Role"})," qui est aussi la Jumelle Villageois. La partie se termine et les mal\xe9fiques gagnent.")),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"Chacune des jumelles d\xe9clare \xeatre l\u2019",(0,a.kt)(i.Z,{ARTISTE:!0,mdxType:"Role"}),". Les deux joueurs vont voir le Conteur pour poser une question en priv\xe9e. Le village, confus, ex\xe9cute le D\xe9mon. La partie continue avec aucune mort la nuit \xe0 partir de maintenant.")),(0,a.kt)("blockquote",null,(0,a.kt)("p",{parentName:"blockquote"},"La ",(0,a.kt)(i.Z,{GUENAUDE:!0,mdxType:"Role"})," transforme un Villageois en Jumelle mal\xe9fique (qui joue toujours pour le village car l'alignement ne change pas). Le village ex\xe9cute ce Jumelle mal\xe9fique. Les mal\xe9fiques gagnent.")),(0,a.kt)("h3",{id:"m\xe9caniques-et-conseils"},"M\xe9caniques et conseils"),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"La premi\xe8re nuit, vous apprenez le r\xf4le de votre jumeau et elle conna\xeet le v\xf4tre. C\u2019est une indication sur un r\xf4le \xe0 bluffer. Pr\xe9tendez avoir le m\xeame r\xf4le que votre jumeau. Evidemment, en bluffant ce r\xf4le, il y aura un doublon avec votre jumeau. N\xe9anmoins, comme votre jumeau va continuellement d\xe9clarer que vous \xeates mal\xe9fique de toute fa\xe7on, pr\xe9tendre le m\xeame r\xf4le ne vas pas plus vous incriminer. En r\xe9alit\xe9, bluffer le r\xf4le de votre jumeau est l\u2019option la moins risqu\xe9e. Si vous bluffez un autre r\xf4le d\xe9j\xe0 en jeu, alors le village saura \xe0 coup s\xfbr que vous \xeates mal\xe9fique. Par exemple, si la jumelle Villageoise est l\u2019",(0,a.kt)(i.Z,{HORLOGER:!0,mdxType:"Role"})," et que la Jumelle mal\xe9fique bluffe l\u2019",(0,a.kt)(i.Z,{HORLOGER:!0,mdxType:"Role"})," , le village saura qu\u2019un des Horlogoers est mal\xe9fique mais ne saura pas lequel. Dans la partie suivante, la jumelle Villageoise est ",(0,a.kt)(i.Z,{MALADROIT:!0,mdxType:"Role"}),"  et la Jumelle mal\xe9fique bluff ",(0,a.kt)(i.Z,{JONGLEUR:!0,mdxType:"Role"})," . Le v\xe9ritable ",(0,a.kt)(i.Z,{JONGLEUR:!0,mdxType:"Role"})," se r\xe9v\xe8le et comme le village sait qu\u2019une des jumelles est mal\xe9fique, ils ex\xe9cutent celui qui pr\xe9tend \xeatre le ",(0,a.kt)(i.Z,{JONGLEUR:!0,mdxType:"Role"}),", car ils savent aussi qu\u2019un des deux Jongleurs ment. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Dites que la jumelle Villageoise est la Jumelle mal\xe9fique. Dites-le encore et encore et encore. Apr\xe8s tout, c\u2019est que la jumelle Villageoise fera. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Soyez tr\xe8s impliqu\xe9 et pas relax\xe9. Parfois, il est pr\xe9f\xe9rable pour un Villageois de mourir et les mal\xe9fiques peuvent aussi le pr\xe9tendre. Cela n\u2019est pas le cas avec les jumelles. Puisque les mal\xe9fiques gagnent imm\xe9diatement si la jumelle Villageoise est ex\xe9cut\xe9, celui-ci sera tr\xe8s insistant pour n\u2019\xeatre ex\xe9cut\xe9 sous aucun pr\xe9texte. Leur situation est similaire \xe0 celle du ",(0,a.kt)(i.Z,{SAINT:!0,mdxType:"Role"}),", dans Trouble Brewing. Une Jumelle mal\xe9fique qui est tranquille \xe0 l'id\xe9e d'\xeatre ex\xe9cut\xe9 le sera probablement car la jumelle Villageoise va beaucoup plus protester.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Une strat\xe9gie possible, bien que pas recommand\xe9e, est de tout nier. Ne jamais dire qu\u2019une Jumelle mal\xe9fique est en jeu. D\xe9clarer que le joueur vous accusant d\u2019\xeatre jumeau ment. Cette strat\xe9gie fonctionne rarement, car le village a un dilemme qui a une r\xe9solution facilit\xe9e. Soit il croit la jumelle Villageoise et vous \xe9x\xe9cute (tuant un Sbire au passage), ou, ils ne croient pas la jumelle Villageoise et l\u2019ex\xe9cute (ce qui met fin \xe0 la partie faisant gagner les mal\xe9fiques). Puisque le risque d\u2019ex\xe9cuter celui qui se pr\xe9tend jumeau Villageois est trop \xe9lev\xe9, la plupart des joueurs choisiront de toujours vous ex\xe9cuter car c\u2019est l\u2019option la moins risqu\xe9e.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Faites-en sorte que la jumelle Villageoise soit ex\xe9cut\xe9 par tous les moyens. Donner des fausses informations qui corroborent les informations de vos camarades mal\xe9fiques. Donnez de vrais informations qui vous rendront digne de confiance. Trouvez tous les arguments pour que le village croit que la jumelle Villageoise est en r\xe9alit\xe9 la Jumelle mal\xe9fique. S\u2019il est ex\xe9cut\xe9, les mal\xe9fiques gagnent.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"De la m\xeame mani\xe8re, si vous \xeatre un mal\xe9fique autre que la Jumelle mal\xe9fique, faites tout ce qui est en votre pouvoir pour soutenir votre Sbire et rendre la jumelle Villageoise suspect. Donner de fausses informations qui rend la jumelle Villageoise suspect. Si la situation le permet, vous pouvez m\xeame donner de bonnes informations, qui rend la jumelle Villageoise suspect (par exemple, si un ",(0,a.kt)(i.Z,{VORTOX:!0,mdxType:"Role"})," est en jeu, vous pouvez pr\xe9tendre \xeatre l\u2019",(0,a.kt)(i.Z,{ARTISTE:!0,mdxType:"Role"})," et avoir su que la Jumelle mal\xe9fique est mal\xe9fique). Soutenez la Jumelle mal\xe9fique et militez pour l\u2019ex\xe9cution du jumeau Villageois.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si vous \xeatre le D\xe9mon, vous pouvez ne pas tuer une nuit pour pr\xe9tendre que le D\xe9mon a \xe9t\xe9 ex\xe9cut\xe9 le jour d\u2019avant. Normalement, si le D\xe9mon est ex\xe9cut\xe9, la partie continue (car tant que la Jumelle mal\xe9fique est en vie, le village ne peut pas gagner). Donc, lorsque le D\xe9mon est ex\xe9cut\xe9, les nuits continuent mais sans mort et le village en d\xe9duit vite qui est le D\xe9mon (le joueur pr\xe9c\xe9demment ex\xe9cut\xe9).  N\xe9anmoins, si vous \xeates toujours en vie et choisissez d\u2019attaquer un joueur mort, on pourra alors supposer que le D\xe9mon a \xe9t\xe9 ex\xe9cut\xe9\u2026 et le pauvre dernier joueur ex\xe9cut\xe9 sera le seul suspect.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si vous \xeates le D\xe9mon, vous pouvez tenter des bluffs plus risqu\xe9s que n\u2019oseriez peut-\xeatre pas tenter dans d\u2019autres parties. Puisque la partie continue si vous mourrez, cela a moins d\u2019importance si vous \xeates ex\xe9cut\xe9. Avec une Jumelle mal\xe9fique en jeu peut \xeatre une bonne opportunit\xe9 pour vous de bluffer le ",(0,a.kt)(i.Z,{SAVANT:!0,mdxType:"Role"}),", le ",(0,a.kt)(i.Z,{REVEUR:!0,mdxType:"Role"}),", le ",(0,a.kt)(i.Z,{CHARMEUR_DE_SERPENT:!0,mdxType:"Role"})," ou le ",(0,a.kt)(i.Z,{FLEURISTE:!0,mdxType:"Role"})," si vous \xeates habituellement peu confiant pour vous y essayer.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Plus rare, mais s\u2019il n\u2019y a pas de Jumelle mal\xe9fique en jeu, deux mal\xe9fiques peuvent bluffer en tant que jumeau gentil. Si les deux d\xe9clarent \xeatre le gentil jumeau, le village va en d\xe9duire que l\u2019un de vous est Jumelle mal\xe9fique et peut \xeatre ex\xe9cut\xe9 l\u2019un d\u2019entre vous. Puisque les deux vont d\xe9clarer \xeatre la jumelle gentille et que l\u2019autre est la Jumelle mal\xe9fique, alors il est mieux que le mal\xe9fique qui est pr\xeat \xe0 mourir se fasse passer plus suspect que l\u2019autre. Dans Sects & Violets, pour bluffer une Jumelle mal\xe9fique, cela pourra n\xe9cessiter qu\u2019un Sbire garde sa capacit\xe9 tr\xe8s discr\xe8te. Par exemple, s\u2019il n\u2019y a qu\u2019un Sbire en jeu et que vous d\xe9clarez que c\u2019est une Jumelle mal\xe9fique, mais qu\u2019un joueur meurt sous l\u2019effet de la sorci\xe8re, tout le monde saura que vous mentez. ")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"S\u2019il n\u2019y a pas de Jumelle mal\xe9fique, un mal\xe9fique peut bluffer comme la jumelle gentille et d\xe9clarer qu\u2019un des Villageois est une Jumelle mal\xe9fique. Evidemment, ce joueur ne saura pas de quoi vous parler et va nier \xeatre la Jumelle mal\xe9fique et m\xeame la jumelle gentille alors faites attention. Toutefois, si vous bluffez bien, vous pourriez r\xe9ussir \xe0 faire ex\xe9cuter ce joueur en le rendant suspect (et vous gentil par la m\xeame occasion) pour le reste de la partie. "))),(0,a.kt)("h3",{id:"combattre-la-jumelle-mal\xe9fique"},"Combattre la Jumelle mal\xe9fique"),(0,a.kt)("ul",null,(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si deux joueurs d\xe9clarent l\u2019autre est la Jumelle mal\xe9fique, alors vous pouvez raisonnablement penser qu\u2019une Jumelle mal\xe9fique est bel et bien en jeu. S\u2019il n\u2019y a qu\u2019un seul Sbire en jeu dans cette partie, vous savez alors que vous \xeates prot\xe9g\xe9 de la ",(0,a.kt)(i.Z,{SORCIERE:!0,mdxType:"Role"}),", du ",(0,a.kt)(i.Z,{MANIPULATEUR:!0,mdxType:"Role"})," ou de la ",(0,a.kt)(i.Z,{GUENAUDE:!0,mdxType:"Role"}),".")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Une fois que vous avez d\xe9termin\xe9 qu\u2019une Jumelle mal\xe9fique est en jeu, il n\u2019y a pas d\u2019urgence a ex\xe9cuter l\u2019un d\u2019entre eux. Si vous prenez une d\xe9cision stupide en d\xe9but de partie et que vous ex\xe9cutez le mauvais jumeau alors les mal\xe9fiques gagneront. Il est pr\xe9f\xe9rable d\u2019attendre quelques jours, ou m\xeame le dernier tiers de la partie avant de d\xe9cider quel pr\xe9tendu jumeau ex\xe9cuter. En attendant, vous aurez eu autant d\u2019informations que possible pour prendre votre d\xe9cision.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Le village DOIT ex\xe9cuter la Jumelle mal\xe9fique pour avoir une chance de gagner. Et ils ne DOIVENT PAS ex\xe9cuter la jumelle gentille ou le village perd imm\xe9diatement. En tant que groupe, mettez la plus grande partie de vos talents de d\xe9duction pour d\xe9terminer le v\xe9ritable alignement des jumelles. Ignorer la rechercher du D\xe9mon tant que vous n\u2019avez pas d\xe9termin\xe9 qui est la Jumelle mal\xe9fique. Si vous tuez le D\xe9mon, la partie continue de toutes fa\xe7ons et vous devez toujours \xe9x\xe9cuter la Jumelle mal\xe9fique pour l\u2019emporter. Puisque les mal\xe9fiques l\u2019emportent si la Jumelle mal\xe9fique et le D\xe9mon sont tous les deux vivants lorsqu\u2019il ne reste que 3 joueurs en vie, vous pourriez avoir besoin d\u2019ex\xe9cuter la Jumelle mal\xe9fique avant d\u2019\xe9x\xe9cuter le D\xe9mon.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Comparez les informations des jumelles pour d\xe9terminer l\u2019alignement des jumelles. Si les deux jumelles pr\xe9tendent \xeatre l\u2019",(0,a.kt)(i.Z,{ARTISTE:!0,mdxType:"Role"})," mais donnent des informations contradictoires, voyez si vous pouvez d\xe9terminer laquelle des deux est vraie. La Jumelle mal\xe9fique est celui qui ment. Le m\xeame raisonnement s\u2019appliquent pour d\u2019autres r\xf4les comme le ",(0,a.kt)(i.Z,{JONGLEUR:!0,mdxType:"Role"})," par exemple.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Certains Villageois peuvent directement aider \xe0 savoir lequel des deux jumelles est r\xe9ellement la Jumelle mal\xe9fique. Un ",(0,a.kt)(i.Z,{CRIEUR_PUBLIC:!0,mdxType:"Role"}),"  peut \xeatre attentif quand un des jumelles nomine. Un ",(0,a.kt)(i.Z,{JONGLEUR:!0,mdxType:"Role"}),"  peut faire un supposition sur la Jumelle mal\xe9fique et apprendre la nuit suivante si c\u2019est correct ou non. Une ",(0,a.kt)(i.Z,{COUTURIERE:!0,mdxType:"Role"}),"  peut d\xe9terminer si la Jumelle mal\xe9fique du m\xeame alignement qu\u2019un autre Villageois. Un ",(0,a.kt)(i.Z,{HORLOGER:!0,mdxType:"Role"}),"  peut obtenir l\u2019information de qui est le D\xe9mon (en se basant sur la distance avec le Sbire le plus proche) puis reprendre le processus dans l\u2019autre sens pour trouver qui est la Jumelle mal\xe9fique en repartant du D\xe9mon. L\u2019",(0,a.kt)(i.Z,{ARTISTE:!0,mdxType:"Role"}),"  peut demander directement. Toutefois, si vous \xeates le ",(0,a.kt)(i.Z,{REVEUR:!0,mdxType:"Role"})," , ne choississez pas l\u2019une des jumelles avec votre capacit\xe9. Tout bon Conteur vous montrera alors Jumelle mal\xe9fique et le r\xf4le qu\u2019ils pr\xe9tendent \xeatre.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Si seulement une personne accuse un joueur d\u2019\xeatre la Jumelle mal\xe9fique, croyez l\u2019acusateur, pas l\u2019accus\xe9. La plupart des jumelles mal\xe9fiques vont aussi d\xe9clarer que leur accusateur est la Jumelle mal\xe9fique mais pas toujours. Dans ce genre de situations, vous avez un choix :  Soit croire que l\u2019accusateur dit la v\xe9rit\xe9 et ex\xe9cuter l\u2019accus\xe9, avec pour cons\xe9quence possible d\u2019avoir tu\xe9 une Sbire. Soit vous croyez que l\u2019accus\xe9 montre la v\xe9rit\xe9 et ex\xe9cuter l\u2019accusateur avec pour cons\xe9quence possible de perdre la partie. Il est bien trop risqu\xe9 de tuer l\u2019accusateur. En tout cas, pas avant d\u2019avoir une preuve solide contre lui. Alors, si vous devez tuer l\u2019un d\u2019entre eux, ex\xe9cuter l\u2019accus\xe9.")),(0,a.kt)("li",{parentName:"ul"},(0,a.kt)("p",{parentName:"li"},"Quand les morts cessent de se produire la nuit, vous avez presque certainement ex\xe9cut\xe9 le D\xe9mon. Puisque la partie continue alors que le D\xe9mon est mort (Le village ne PEUT PAS gagner tant que la Jumelle mal\xe9fique est en vie) le D\xe9mon est certainement mort et ne peut plus tuer la nuit."))),(0,a.kt)("h3",{id:"comment-conter"},"Comment conter?"),(0,a.kt)("p",null,'En pr\xe9parant le Grimoire, choisissez une jumelle gentil en marquant un joueur gentil avec le jeton de rappel "Jumelle". Durant la premi\xe8re nuit, r\xe9veillez les jumelles. Laissez-les avoir un contact visuel. D\xe9signez la Jumelle mal\xe9fique et montrez ensuite le jeton de r\xf4le de la Jumelle mal\xe9fique au joueur gentil. D\xe9signez la jumelle gentille et montrez le jeton de r\xf4le de ce joueur au Jumelle mal\xe9fique. Rendormez-les ensuite. '),(0,a.kt)("p",null,"Tant que les deux jumelles sont en vie, le village ne peut pas gagner. Si la jumelle gentille est ex\xe9cut\xe9, les mal\xe9fiques gagnent."),(0,a.kt)("p",null,(0,a.kt)("em",{parentName:"p"},"Si la Guenaude cr\xe9\xe9 une Jumelle mal\xe9fique durant la derni\xe8re nuit, vous pouvez soit choisir le D\xe9mon comme jumeau ou un joueur mort pour que le village ait toujours une chance de gagner.")),(0,a.kt)("p",null,(0,a.kt)("em",{parentName:"p"},"c\u2019est rarement une bonne id\xe9e de choisir un Voyageur d\u2019\xeatre une jumelle")))}c.isMDXComponent=!0}}]);